    17  Service_OpenSecureChannel(UA_Server *server, UA_SecureChannel *channel,
    18                            const UA_OpenSecureChannelRequest *request,
    19                            UA_OpenSecureChannelResponse *response) {
    20      if(request->requestType == UA_SECURITYTOKENREQUESTTYPE_RENEW) {
    21          /* Renew the channel */
    22          response->responseHeader.serviceResult =
    23              UA_SecureChannelManager_renew(&server->secureChannelManager,
    24                                            channel, request, response);
    25
    26          /* Logging */
    27          if(response->responseHeader.serviceResult == UA_STATUSCODE_GOOD) {
    28              UA_LOG_DEBUG_CHANNEL(server->config.logger, channel,
    29                                   "SecureChannel renewed");
    30          } else {
    31              UA_LOG_DEBUG_CHANNEL(server->config.logger, channel,
    32                                   "Renewing SecureChannel failed");
    33          }
    34          return;
    35      }
    36
    37      /* Must be ISSUE or RENEW */
    38      if(request->requestType != UA_SECURITYTOKENREQUESTTYPE_ISSUE) {
    39          response->responseHeader.serviceResult = UA_STATUSCODE_BADINTERNALERROR;
    40          return;
    41      }
    42
    43      /* Open the channel */
    44      response->responseHeader.serviceResult =
    45          UA_SecureChannelManager_open(&server->secureChannelManager, channel,
    46                                       request, response);
    47
    48      /* Logging */
    49      if(response->responseHeader.serviceResult == UA_STATUSCODE_GOOD) {
    50          UA_LOG_INFO_CHANNEL(server->config.logger, channel,
    51                              "Opened SecureChannel");
    52      } else {
    53          UA_LOG_INFO_CHANNEL(server->config.logger, channel,
    54                              "Opening a SecureChannel failed");
    55      }
    56  }
